import React from 'react'
import { useDataLayerValue } from '../DataLayer'
import content from '../content';



function Profile() {

    const [{page},dispatch] = useDataLayerValue();

    const mainPage = () => {
        dispatch({
          type: "SET_PAGE",
          page: "main",
        });
      }


    return (
        <div>
            <img className={"absolute mx-4 my-2 opacity-40 hover:opacity-100"} onClick={mainPage} src={content.back}></img>
            <div className={"w-screen h-screen flex flex-wrap place-content-center"}>
                <div className={"inline-flex"}>
                    <div className={"w-48 h-48 bg-yellow-500"} >

                    </div>
                    <div className={"w-48 h-48 bg-yellow-800"} >

                    </div>
                </div>
            </div>
        </div>
    )
}

export default Profile
